package com.example

import com.example.ExamQuestionHelper.QSpec

object HealthLiveExamMentalSkillsBank2 {
    private const val T = "මානසික සුවතාව, ජීවන නිපුණතා හා මත්ද්‍රව්‍ය නිවාරණය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("ඖෂධ හෝ මත්ද්‍රව්‍ය භාවිතයේදී කාලයත් සමග පෙර දැනුණු ප්‍රතිඵලයම ලබාගැනීම සඳහා වැඩි වැඩියෙන් මාත්‍රාව වැඩි කිරීමට සිදුවීම හඳුන්වන්නේ කෙසේද?", "දරාගැනීමේ හැකියාව හෙවත් සහනශීලතාව (Drug Tolerance)", "ඉවත් වීමේ ලක්ෂණ", "ආසාත්මිකතාව", "විෂහරණය", "මොළයේ ප්‍රතිග්‍රාහක මත්ද්‍රව්‍යයට හුරුවීම නිසා පෙර මාත්‍රාව ප්‍රමාණවත් නොවීම Drug Tolerance වේ."),
        q("මත්ද්‍රව්‍යයක් දිගුකාලීනව භාවිත කිරීමෙන් පසු ශරීරය එම රසායනිකය නොමැතිව සාමාන්‍ය ලෙස ක්‍රියා කළ නොහැකි තත්ත්වයට පත්වීම කුමක්ද?", "කායික පරායත්තතාව (Physical Dependence)", "සමාජ අවබෝධය", "ධනාත්මක චින්තනය", "ස්වයං විශ්වාසය", "ශරීර පටක මත්ද්‍රව්‍යයට අනුවර්තනය වීම නිසා එය නැවැත්වූ විට කායික වේදනා හා රෝග ලක්ෂණ හටගනී."),
        q("මත්ද්‍රව්‍යයක් නොලැබුණහොත් තමාට සතුටින් සිටිය නොහැකි බවට මනස තුළ ඇතිවන දැඩි ආශාව සහ බැඳීම කුමක්ද?", "මානසික පරායත්තතාව (Psychological Dependence)", "කායික යෝග්‍යතාව", "චිත්තවේග බුද්ධිය", "නිර්මාණශීලීත්වය", "මානසික ආතතියෙන් මිදීමට හෝ සතුට සෙවීමට මත්ද්‍රව්‍යය මත මනස රඳා පැවතීම Psychological Dependence වේ."),
        q("මධ්‍යම ස්නායු පද්ධතියේ ක්‍රියාකාරිත්වය වේගවත් කර තාවකාලික අධි උද්යෝගයක් ඇති කරන උත්තේජක (Stimulants) කාණ්ඩයට අයත් මත්ද්‍රව්‍යය කුමක්ද?", "කොකේන් සහ මෙතැම්ෆෙටමින් (අයිස්)", "මෝෆීන් සහ හෙරොයින්", "ඇල්කොහොල්", "නිද්‍රා ඖෂධ", "උත්තේජක මත්ද්‍රව්‍ය මගින් හෘද ස්පන්දනය, රුධිර පීඩනය සහ මොළයේ අවදි බව කෘත්‍රිමව ඉහළ දමයි."),
        q("මධ්‍යම ස්නායු පද්ධතියේ ක්‍රියාකාරිත්වය මන්දගාමී කර නිදිමත හා අවධානය අඩු කරන මර්දනකාරී (Depressants) කාණ්ඩයට අයත් ද්‍රව්‍යය කුමක්ද?", "මධ්‍යසාර (Alcohol) සහ නිද්‍රාජනක ඖෂධ", "නිකොටින්", "කැෆේන්", "කොකේන්", "මධ්‍යසාර ස්නායු ආවේග සම්ප්‍රේෂණය මන්දගාමී කරන ප්‍රබල Depressant ද්‍රව්‍යයකි."),
        q("පුද්ගලයාගේ ඉන්ද්‍රිය සංවේදන විකෘති කර සැබැවින් නොමැති දේ පෙනීම හා ඇසීම ඇති කරන මනෝභ්‍රාන්තිකාරක (Hallucinogens) ද්‍රව්‍යය කුමක්ද?", "LSD සහ අධි සාන්ද්‍රිත ගංජා (THC)", "පැරසිටමෝල්", "විටමින් C", "සේලයින්", "මනෝභ්‍රාන්තිකාරක මගින් කාලය, අවකාශය සහ යථාර්ථය පිළිබඳ මොළයේ සංජානනය අවුල් කෙරේ."),
        q("මත්ද්‍රව්‍යයකට ඇබ්බැහි වූ අයෙකුගේ ශරීරයෙන් එම විෂ ද්‍රව්‍ය වෛද්‍ය අධීක්ෂණය යටතේ ඉවත් කිරීමේ ප්‍රතිකාර ක්‍රියාවලිය කුමක්ද?", "විෂහරණය කිරීම හෙවත් ඩිටොක්සිෆිකේෂන් (Detoxification)", "පෝෂණය කිරීම", "ව්‍යායාම පුහුණුව", "පුනරුච්චාරණය", "පුනරුත්ථාපනයේ පළමු පියවර වන මෙහිදී ඉවත් වීමේ රෝග ලක්ෂණ පාලනය කරමින් සිරුර පිරිසිදු කෙරේ."),
        q("දීර්ඝකාලීන දුම්පානය නිසා පෙනහලුවල වායු කෝෂ බිත්ති බිඳී ගොස් හුස්ම ගැනීම අතිශය අපහසු වන නිදන්ගත රෝගය කුමක්ද?", "එම්ෆයිසීමා රෝගය (Emphysema / COPD)", "මැලේරියාව", "ඩෙංගු", "ජලභීතිකාව", "දුම්වැටි දුම නිසා වායු කෝෂවල ප්‍රත්‍යස්ථතාව නැති වී ඔක්සිජන් හුවමාරුව අඩපණ වේ."),
        q("දුම්වැටිවල අඩංගු නිකොටින් මගින් හෘදය හා රුධිර සංසරණ පද්ධතියට සිදුකරන ප්‍රධාන හානිය කුමක්ද?", "රුධිර නාල සංකෝචනය කර රුධිර පීඩනය ඉහළ දැමීම සහ ධමනි තුළ මේද තැන්පත් වීම වේගවත් කිරීම", "රුධිර නාල පිරිසිදු කිරීම", "හෘද ස්පන්දනය සමබර කිරීම", "කොලෙස්ටරෝල් අඩු කිරීම", "දුම්පානය කිරීටක ධමනි අවහිර වී හෘදයාබාධ හා ආඝාතය ඇතිවීමේ අවදානම දෙගුණ තෙගුණ කරයි."),
        q("වෛද්‍ය නිර්දේශයකින් තොරව නිවසේ ඇති වේදනා නාශක හෝ කැස්ස පැණි වර්ග අධික ලෙස පානය කිරීම හඳුන්වන්නේ කෙසේද?", "ඖෂධ අවභාවිතය (Drug Misuse / Prescription Abuse)", "නිවැරදි ප්‍රතිකාරය", "ප්‍රථමාධාරය", "ආහාර අතිරේක", "නීත්‍යානුකූල ඖෂධ පවා වෛද්‍ය උපදෙස්වලින් තොරව වැරදි මාත්‍රාවෙන් ගැනීම ඇබ්බැහිවීමකට හා අවයව හානියට මුල් වේ."),
        q("තරුණයන් අතර බුලත් විටට අමතරව දුම්කොළ කුඩු හා රසකාරක මිශ්‍ර කර දත් විදුරුමස යට තබා ගැනීමේ අහිතකර පුරුද්ද කුමක්ද?", "බාබුල්, මාවා හා තුල් වැනි දුම්රහිත දුම්කොළ නිෂ්පාදන (Smokeless Tobacco) භාවිතය", "දත් මැදීම", "විටමින් ගැනීම", "පළතුරු කෑම", "දුම් රහිත දුම්කොළ නිෂ්පාදන මුඛ පිළිකා සහ දත් විදුරුමස් දියවීම ඉතා වේගයෙන් ඇති කරයි."),
        q("තම හැඟීම් ප්‍රකාශ කිරීමේදී අනෙකාට දොස් පවරන 'ඔබ' ප්‍රකාශ (You-statements) වෙනුවට භාවිත කළ යුතු සාර්ථක සන්නිවේදන ක්‍රමය කුමක්ද?", "'මම' ප්‍රකාශ භාවිතය (I-statements — උදාහරණයක් ලෙස මට මෙසේ දැනෙනවා)", "තර්ජනාත්මක ප්‍රකාශ", "නිහඬව සිටීම", "අපහාස කිරීම", "'ඔබ හැමවිටම වැරදියි' යැයි කීම වෙනුවට 'මට මෙයින් කනගාටුවක් දැනෙනවා' ලෙස පැවසීමෙන් ගැටුම් අවම වේ."),
        q("මානසික ආතතිය හඳුනාගෙන සමනය කිරීම සඳහා මාංශ පේශි ක්‍රමානුකූලව තද කර ලිහිල් කිරීමේ විද්‍යාත්මක ක්‍රමය කුමක්ද?", "ප්‍රගතිශීලී මාංශ පේශි ලිහිල්කරණය (Progressive Muscle Relaxation — PMR)", "බර එසවීම", "වේගයෙන් දිවීම", "නින්ද නොගොස් සිටීම", "පාදයේ සිට හිස දක්වා පේශි කාණ්ඩ තත්පර 5ක් තද කර තත්පර 10ක් ලිහිල් කිරීමෙන් කායික ආතතිය පහව යයි."),
        q("පුද්ගලයෙකු තමා පිළිබඳවම ගොඩනගාගෙන සිටින සිතුවිලි හා විශ්වාසයන් සමූහය හඳුන්වන්නේ කෙසේද?", "ස්වයං සංකල්පය (Self-concept)", "පරමාදර්ශී ආත්මය", "සමාජ තත්ත්වය", "බුද්ධි මට්ටම", "මම කවුද, මගේ හැකියාවන් මොනවාද යන්න පිළිබඳව තමා සතු මානසික චිත්‍රය ස්වයං සංකල්පයයි."),
        q("පුද්ගලයෙකු අනාගතයේදී තමා කෙබඳු අයෙකු වීමට කැමැත්තේද යන්න පිළිබඳ සිතේ ඇති ඉලක්කගත ප්‍රතිරූපය කුමක්ද?", "පරමාදර්ශී ආත්මය (Ideal Self)", "සැබෑ ආත්මය", "ආත්ම අනුකම්පාව", "සමාජ බිය", "සැබෑ ආත්මය සහ පරමාදර්ශී ආත්මය අතර පරතරය අඩු වන විට පුද්ගලයා තුළ ඉහළ තෘප්තියක් ඇතිවේ."),
        q("මිතුරන් අතර සිදුවන 'නවකවදය' හෝ පාසල් හිරිහැර කිරීම (Bullying) පිළිබඳ නිවැරදි අදහස කුමක්ද?", "එය ශක්තිය හෝ බලය අයුතු ලෙස යොදා ගනිමින් දුර්වල අයෙකුට දිගින් දිගටම කරන මානසික හා කායික හිංසනයකි", "එය මිත්‍රත්වය තහවුරු කරන විනෝදයකි", "එය පාසල් සම්ප්‍රදායකි", "එයින් කිසිවෙකුට හානියක් නැත", "හිරිහැර කිරීම් නිසා වින්දිතයාගේ අධ්‍යාපනය කඩාකප්පල් වී දැඩි මානසික අවපීඩනය ඇතිවිය හැක."),
        q("පාසලේ හෝ බස් රථයේදී වෙනත් සිසුවෙකු හිරිහැරයට ලක්වනු දුටු විට වගකිවයුතු ශිෂ්‍යයෙකු (Upstander) කළ යුත්තේ කුමක්ද?", "හිංසනයට අනුබල නොදී වින්දිතයාට සහය වෙමින් ගුරුවරයෙකු හෝ වැඩිහිටියෙකු දැනුවත් කිරීම", "එය වීඩියෝ කර සිනාසීම", "තමාද එයට එක් වීම", "අහක බලාගෙන යාම", "නිහඬව බලා සිටීම (Bystander) වෙනුවට අසාධාරණයට එරෙහිව නැගී සිටීමෙන් හිරිහැර නතර කළ හැක."),
        q("හදිසියේම ඇතිවන දැඩි මරණ බිය, හුස්ම ගැනීමේ අපහසුව, පපුවේ වේදනාව සහ කරකැවිල්ල සමග විනාඩි කිහිපයක් පවතින කාංසා ප්‍රහාරය කුමක්ද?", "සන්ත්‍රාස ප්‍රහාරය හෙවත් පැනික් ඇටෑක් (Panic Attack)", "හෘදයාබාධය පමණි", "මීමැස්මොරය", "උණ සන්නිපාතය", "පැනික් ඇටෑක් එකකදී කිසිදු ශාරීරික හෘද රෝගයක් නොතිබුණද මොළයේ බිය මධ්‍යස්ථානය ක්ෂණිකව උත්තේජනය වේ."),
        q("මානසික රෝගයක් වැළඳුණු පුද්ගලයෙකු සම්බන්ධයෙන් සමාජයේ පවතින වැරදි මිථ්‍යා මතයක් වන්නේ කුමක්ද?", "මානසික රෝග යනු භූත දෝෂ හෝ පෙර කර්ම නිසා සිදුවන බවත් වෛද්‍ය ප්‍රතිකාරවලින් සුව කළ නොහැකි බවත් සිතීම", "මනෝ වෛද්‍යවරුන් හමුවීම සුදුසු බව", "පවුලේ සහය වැදගත් බව", "ඖෂධවලින් පාලනය කළ හැකි බව", "මානසික රෝගද අනෙකුත් ශාරීරික රෝග මෙන්ම මොළයේ රසායනික වෙනස්කම් නිසා හටගන්නා සුව කළ හැකි රෝග වේ."),
        q("මානසික රෝගයක් ඇතිවූ විට දේවාල, යන්ත්‍ර මන්ත්‍ර පසුපස යාමෙන් සිදුවන බරපතළ අවාසිය කුමක්ද?", "නිසි වෛද්‍ය ප්‍රතිකාර ප්‍රමාද වී රෝගය උත්සන්න වීම සහ රෝගියාට ශාරීරික හිංසා සිදුවීම", "රෝගය වහාම සුව වීම", "මුදල් ඉතිරි වීම", "වෛද්‍ය දැනුම වැඩිවීම", "කල්තියා මනෝ වෛද්‍ය ප්‍රතිකාර ලබාගැනීමෙන් මානසික රෝග ඉතා සාර්ථකව පාලනය කළ හැක."),
        q("තීරණ ගැනීමේදී භාවිත කළ හැකි DECIDE ආකෘතියේ පළමු පියවර වන 'D' අකුරෙන් අදහස් කරන්නේ කුමක්ද?", "ගැටලුව හෝ තීරණය කළ යුතු කාරණය පැහැදිලිව නිර්වචනය කිරීම (Define the problem)", "තීරණය ප්‍රමාද කිරීම", "අනුන්ගෙන් ඇසීම", "තීරණය මකා දැමීම", "Define, Explore alternatives, Consider consequences, Identify values, Decide & act, Evaluate යනු මෙහි පියවරයි."),
        q("කෙනෙකුගේ ජීවිතයේ අභියෝග හමුවේ මානසිකව බිඳ නොවැටී ඉක්මනින් නැවත යථා තත්ත්වයට පත්වීමේ ශක්තිය කුමක්ද?", "මානසික ඔරොත්තු දීමේ හැකියාව (Mental Resilience)", "මානසික දුර්වලතාව", "කම්මැලිකම", "බියගුලුකම", "දුෂ්කර අවස්ථාවලින් පන්නරය ලබා නැවත නැගී සිටීමේ හැකියාව Mental Resilience නම් වේ."),
        q("සිසුන් තුළ මානසික ඔරොත්තු දීමේ හැකියාව (Resilience) වර්ධනය කර ගැනීමට උපකාරී වන ප්‍රධාන සාධකයක් වන්නේ කුමක්ද?", "ශක්තිමත් සමාජ ආධාරක ජාලයක් (දෙමාපියන්, ගුරුවරුන්, හොඳ මිතුරන්) පැවතීම", "සැමවිටම තනිව සිටීම", "ගැටලු සඟවා තබා ගැනීම", "අධික තරගකාරිත්වය", "තමාට උදව් කිරීමට විශ්වාසවන්ත පිරිසක් සිටින බව දැනීම ඕනෑම අර්බුදයකදී මානසික ශක්තිය සපයයි."),
        q("කාල කළමනාකරණයේදී 'ප්‍රමුඛතාකරණය' (Prioritization) යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "වඩාත්ම වැදගත් සහ හදිසි කටයුතු මුලින් හඳුනාගෙන ඒවාට ප්‍රමුඛත්වය දී ඉටු කිරීම", "සියලු වැඩ අතහැර දැමීම", "අනවශ්‍ය වැඩ මුලින් කිරීම", "කිසිදු සැලැස්මක් නොමැති වීම", "අයිසන්හවර් න්‍යාය (Urgent vs Important) අනුව කටයුතු පෙළගැස්වීමෙන් කාලය නාස්ති වීම වැළකේ."),
        q("වැඩ කටයුතු අද නොකර හෙටට කල් දැමීමේ පුරුද්ද (Procrastination) නිසා ඇතිවන ප්‍රධාන මානසික ප්‍රතිවිපාකය කුමක්ද?", "අවසන් මොහොතේ අධික මානසික ආතතියක්, කාංසාවක් හා කලබලයක් ඇතිවීම", "කාලය ඉතිරි වීම", "මානසික සැහැල්ලුව වැඩිවීම", "වැඩවල ගුණාත්මකභාවය වැඩිවීම", "වැඩ කල් දැමීම නිසා පීඩනය ගොඩගැසී පසුව කාර්යයන් නිසි පරිදි ඉටු කිරීමට නොහැකි වේ."),
        q("අධ්‍යයන කටයුතු කරන අතරතුර සුළු විවේකයක් ගැනීම (උදාහරණයක් ලෙස විනාඩි 45කට වරක් විනාඩි 5-10ක්) මනසට වැදගත් වන්නේ ඇයි?", "මොළයේ අවධානය සහ මතක ශක්තිය නැවත අලුත් වී මානසික වෙහෙස දුරු වන බැවින්", "පාඩම් අමතක වන නිසා", "කාලය නාස්ති වන නිසා", "නින්ද යන නිසා", "පොමොඩෝරෝ වැනි කෙටි විවේක ක්‍රම මගින් දිගු වේලාවක් ඉහළ ඒකාග්‍රතාවයකින් ඉගෙනීමට හැකිවේ."),
        q("දුම්වැටි හෝ මත්පැන්වලට වියදම් වන මුදල පවුලේ පෝෂණයට හා දරුවන්ගේ අධ්‍යාපනයට යෙදවීමෙන් සමාජයට සිදුවන යහපත කුමක්ද?", "පවුලේ ජීවන තත්ත්වය උසස් වී දරුවන්ගේ අනාගතය හා සෞඛ්‍යය සුරක්ෂිත වීම", "රජයේ බදු අඩු වීම", "වෙළඳුන් පොහොසත් වීම", "කිසිදු වෙනසක් නොවීම", "දුම්කොළ හා මත්පැන් සඳහා දෛනිකව නාස්ති වන විශාල ධනය ඉතිරි කිරීම දරිද්‍රතාවය පිටුදැකීමට මග පාදයි."),
        q("මත්පැන් පානය නිසා රුධිර වාහිනීවලට හා හෘද පේශිවලට ඇතිවන දීර්ඝකාලීන රෝගී තත්ත්වයක් වන්නේ කුමක්ද?", "අධි රුධිර පීඩනය සහ හෘද පේශි දුර්වල වීම (Alcoholic Cardiomyopathy)", "රුධිරය වැඩිවීම", "හෘදය ශක්තිමත් වීම", "පෙනහලු පිරිසිදු වීම", "දිගුකාලීන මත්පැන් භාවිතය හෘද පේශි විශාල වී දුර්වල වීමට හා ආඝාතයට හේතු වේ."),
        q("ගර්භණී කාන්තාවක් මත්පැන් පානය කිරීම නිසා කුස තුළ සිටින බිළිඳාට ඇතිවන මොළයේ හා මුහුණේ විකෘතිතා තත්ත්වය කුමක්ද?", "කලල මධ්‍යසාර සින්ඩ්‍රෝමය (Fetal Alcohol Syndrome — FAS)", "ඩවුන් සින්ඩ්‍රෝමය", "හිමොෆීලියාව", "තැලසීමියාව", "මව බොන මත්පැන් වැදෑමහ හරහා කලලයට ගොස් කුඩා හිසක්, බුද්ධි ඌනතාව සහ වර්ධන බාධා ඇති කරයි."),
        q("මත්ද්‍රව්‍යවලට ඇබ්බැහි වූ පුද්ගලයන් සමාජයෙන් කොන් නොකර ඔවුන් පුනරුත්ථාපනය කිරීමේදී අත්‍යවශ්‍ය වන්නේ කුමක්ද?", "වෛද්‍ය ප්‍රතිකාර, මනෝ උපදේශනය, වෘත්තීය පුහුණුව සහ පවුලේ ආදරණීය රැකවරණය", "සිරගත කිරීම පමණි", "ශාරීරික දඬුවම් දීම", "නිවසින් පන්නා දැමීම", "නැවත සමාජගත කිරීමේදී සුදුසු රැකියාවක් හා පවුලේ පිළිගැනීම නැවත ඇබ්බැහි වීම (Relapse) වළක්වයි."),
        q("පුනරුත්ථාපනය වූ මත්ද්‍රව්‍ය භාවිත කළ අයෙකු නැවත වරක් පැරණි මිතුරන් හමුවීම නිසා යළි මත්ද්‍රව්‍යවලට පෙළඹීම හඳුන්වන්නේ කෙසේද?", "ප්‍රතිවර්තනය හෙවත් නැවත ඇබ්බැහි වීම (Relapse)", "සම්පූර්ණ සුවය", "ඩිටොක්සිෆිකේෂන්", "සහනශීලතාව", "පුනරුත්ථාපනයෙන් පසු පැරණි අවදානම් පරිසරයෙන් හා පෙළඹවීම්වලින් ඈත්ව සිටීම ඉතා වැදගත් වේ."),
        q("දුම්පානයෙන් මිදීමට උත්සාහ කරන පුද්ගලයෙකුට දුම්වැටියකට ඇති ආශාව පාලනය කිරීමට උපකාරී වන '4D' උපක්‍රමයේ එක් පියවරක් කුමක්ද?", "ප්‍රමාද කිරීම (Delay), ගැඹුරින් හුස්ම ගැනීම (Deep breathe), ජලය පානය (Drink water), අවධානය වෙනතකට යොමු කිරීම (Distract)", "දුම්වැටියක් පත්තු කිරීම", "තනිව සිටීම", "කෝපි බීම", "දුම්වැටි ආශාව (Craving) පවතින්නේ විනාඩි 3-5ක් පමණක් බැවින් 4D ක්‍රමයෙන් එම මොහොත ජයගත හැක."),
        q("මානව සන්නිවේදනයේදී වචනවලින් තොරව මුහුණේ ඉරියව්, ඇස් සම්බන්ධතාව සහ අත් චලන මගින් අදහස් පළ කිරීම කුමක්ද?", "නිර්වාචික සන්නිවේදනය (Non-verbal Communication)", "වාචික සන්නිවේදනය", "ලිඛිත සන්නිවේදනය", "විද්‍යුත් සන්නිවේදනය", "පුද්ගලයෙකුගේ සැබෑ හැඟීම් සහ ආත්ම විශ්වාසය බොහෝ විට පිළිබිඹු වන්නේ නිර්වාචික සන්නිවේදනයෙනි."),
        q("පාසල් සිසුවෙකු සිය දෛනික කාලසටහන සකස් කිරීමේදී අනිවාර්යයෙන්ම වෙන් කළ යුතු කාල පරාස මොනවාද?", "අධ්‍යයන කටයුතු, ශාරීරික ක්‍රීඩා හා ව්‍යායාම, පවුලේ අය සමග කාලය සහ ප්‍රමාණවත් නින්ද", "පැය 24ම පාඩම් කිරීම", "සම්පූර්ණ දවසම රූපවාහිනිය බැලීම", "නින්ද සම්පූර්ණයෙන් කපා හැරීම", "සමබර දෛනික කාලසටහනකින් ශාරීරික, මානසික හා අධ්‍යාපනික සංවර්ධනය එකවර සිදුවේ."),
        q("අධික තරගකාරී අධ්‍යාපන රටාව තුළ සිසුන් තුළ ඇතිවන 'පරීක්ෂණ කාංසාව' (Exam Anxiety) අවම කර ගැනීමට කළ යුත්තේ කුමක්ද?", "කලින්ම ක්‍රමානුකූලව පාඩම් ආවරණය කිරීම, පෙරහුරු ප්‍රශ්න පත්‍ර කිරීම සහ විභාග දින හොඳ නින්දක් ලබාගැනීම", "විභාගයට පෙර රාත්‍රියේ නිදි නොලබා සිටීම", "විභාග ශාලාවට අන්තිම මොහොතේ දුවගෙන යාම", "අනෙක් අය සමග තම ලකුණු ගැන නිතරම වද වීම", "සූදානම සහ විශ්වාසය විභාග බිය තුරන් කරන හොඳම ඖෂධයයි."),
        q("පුද්ගලයෙකුගේ ආත්ම ගරුත්වයට හා සමාජ තත්ත්වයට හානි කරන කටකතා සහ අසත්‍ය ප්‍රචාර හඳුන්වන්නේ කෙසේද?", "වාචික හා සමාජීය හිරිහැර (Verbal & Social Bullying)", "සාධාරණ විවේචන", "සහකම්පනය", "ධනාත්මක සන්නිවේදනය", "අසත්‍ය ප්‍රචාර හා කොන් කිරීම් අනෙකාගේ මානසික සෞඛ්‍යයට දැඩි ලෙස හානි පමුණුවයි."),
        q("සමාජ මාධ්‍ය භාවිතයේදී අනෙක් අයගේ සුඛෝපභෝගී ජීවිත දෙස බලා තමාගේ ජීවිතය ගැන කලකිරීමට පත්වීම වළක්වා ගැනීමට තිබිය යුතු අවබෝධය කුමක්ද?", "සමාජ මාධ්‍යවල පළ වන්නේ ජීවිතයේ තෝරාගත් අලංකාර අවස්ථා පමණක් බවත් සැබෑ යථාර්ථය ඊට වෙනස් බවත් වටහා ගැනීම", "සමාජ මාධ්‍යවල සෑම දෙයක්ම 100% සත්‍ය බව සිතීම", "තමාද ණය වී හෝ පෙන්වීමට කටයුතු කිරීම", "සමාජයට වෛර කිරීම", "විචාරශීලීව සමාජ මාධ්‍ය දෙස බැලීමෙන් ඊර්ෂ්‍යාව හා ආත්ම අවපීඩනය වළක්වා ගත හැක."),
        q("ශ්‍රී ලංකාවේ හදිසි මානසික අසහනයකදී හෝ ආපදාවකදී පවුලේ සාමාජිකයන්ගෙන් ලැබෙන ප්‍රථම හා වටිනාම සහය කුමක්ද?", "කිසිදු විනිශ්චයකින් තොරව ආදරයෙන් සවන් දීම සහ රැකවරණය සැලසීම", "දෝෂාරෝපණය කිරීම", "අවඥාවෙන් සිනාසීම", "තනි කර දමා යාම", "ආදරණීය පවුලේ සවන්දීම බොහෝ මානසික අර්බුදවලින් පුද්ගලයා බේරා ගැනීමට සමත් වේ."),
        q("ලෝක මානසික සෞඛ්‍ය දිනය (World Mental Health Day) ජාත්‍යන්තරව සමරනු ලබන්නේ සෑම වසරකම කුමන දිනයේදීද?", "ඔක්තෝබර් 10 වන දින", "මැයි 31 වන දින", "දෙසැම්බර් 1 වන දින", "අප්‍රේල් 7 වන දින", "මානසික සෞඛ්‍ය පිළිබඳ දැනුවත්භාවය ඉහළ නැංවීමට සෑම වසරකම ඔක්තෝබර් 10 දින වෙන් කර ඇත."),
        q("ලෝක දුම්කොළ විරෝධී දිනය (World No Tobacco Day) WHO මගින් ප්‍රකාශයට පත් කර ඇත්තේ කුමන දිනයේද?", "මැයි 31 වන දින", "ඔක්තෝබර් 10 වන දින", "ජුනි 26 වන දින", "දෙසැම්බර් 1 වන දින", "දුම්කොළ භාවිතයේ ආදීනව ලොවට හඬගා කීමට සෑම වසරකම මැයි 31 වන දින යොදා ගැනේ."),
        q("මත්ද්‍රව්‍ය අවභාවිතයට හා නීති විරෝධී ජාවාරමට එරෙහි ජාත්‍යන්තර දිනය කවදාද?", "ජුනි 26 වන දින", "මැයි 31 වන දින", "ඔක්තෝබර් 10 වන දින", "නොවැම්බර් 14 වන දින", "එක්සත් ජාතීන්ගේ සංවිධානය විසින් සෑම වසරකම ජුනි 26 දින මත්ද්‍රව්‍ය විරෝධී දිනය ලෙස නම් කර ඇත."),
        q("රැකියා ස්ථානයේ හෝ පාසලේදී විඩාවට පත් වූ මනස නැවත ප්‍රකෘතිමත් කර ගැනීමට උපකාරී වන 'ප්‍රකෘති සුවය' ලබාදෙන ස්වාභාවික පරිසර ක්‍රියාකාරකම කුමක්ද?", "සොබාදහම සමග ගැවසීම, ගස්වැල් නැරඹීම සහ එළිමහන් ඇවිදීම", "අඳුරු කාමරයක වසාගෙන සිටීම", "අධික ශබ්දය ඇති ස්ථානවල රැඳීම", "විෂ දුම් ආඝ්‍රාණය කිරීම", "සොබාදහම සමග කාලය ගත කිරීමෙන් කෝටිසෝල් ආතති හෝමෝනය පහත වැටී මනස සැහැල්ලු වේ."),
        q("පුද්ගලයෙකු තුළ 'සානුකම්පිත සවන්දීම' (Empathetic Listening) පවතින බව හඳුනාගන්නේ කෙසේද?", "කතා කරන්නාට බාධා නොකර, විනිශ්චය නොකර, ඔහුගේ හැඟීම් වටහා ගනිමින් අවධානයෙන් සවන් දීමෙන්", "තමාගේම කතාවක් මැදින් පැවසීමෙන්", "දුරකථනය දෙස බලාගෙන සිටීමෙන්", "සිනාසීමෙන්", "විනිශ්චයෙන් තොරව සවන් දීම නිසා පීඩිත පුද්ගලයාට තම හදවතේ බර සැහැල්ලු කර ගැනීමට අවස්ථාව ලැබේ."),
        q("මත්පැන් හා දුම්වැටි භාවිතය ප්‍රතික්ෂේප කිරීමෙන් ක්‍රීඩකයෙකුට ලැබෙන සෘජු කායික වාසිය කුමක්ද?", "පෙනහලු ධාරිතාව, හෘද ස්පන්දන කාර්යක්ෂමතාව සහ මාංශ පේශි දරාගැනීමේ හැකියාව උපරිමව පැවතීම", "වේගය අඩුවීම", "ඉක්මනින් හති වැටීම", "අස්ථි බිඳී යාම", "දුම්පානයෙන් හා මත්පැන්වලින් තොර ක්‍රීඩකයාට උපරිම ශ්වසන හා කායික ක්‍රියාකාරිත්වයක් පවත්වා ගත හැක."),
        q("තම මනසේ ඇතිවන අනවශ්‍ය සෘණාත්මක සිතුවිලි පාලනය කර ගැනීමට කළ හැකි සරල ඥානාත්මක ක්‍රමයක් කුමක්ද?", "සෘණාත්මක සිතුවිලි හඳුනාගෙන ඒවා වෙනුවට යථාර්ථවාදී ධනාත්මක සිතුවිලි ආදේශ කිරීම (Cognitive Reframing)", "ඒ ගැනම දිගින් දිගටම කල්පනා කරමින් ඇඬීම", "අන් අයට දොස් කීම", "නින්දට බාධා කර ගැනීම", "සිතුවිලි දෙස නව කෝණයකින් බැලීමෙන් කාංසාව හා අසහනය සැලකිය යුතු ලෙස අඩු කරගත හැක."),
        q("සෞඛ්‍ය සම්පන්න ශ්‍රී ලංකාවක් ගොඩනැගීම සඳහා 'මත්ද්‍රව්‍යවලින් තොර තරුණ පරපුරක්' බිහිකිරීම අතිශයින්ම වැදගත් වන්නේ මන්ද?", "තරුණ පරපුර රටේ ජවය, නිෂ්පාදන ශක්තිය හා අනාගත නායකත්වය නියෝජනය කරන ප්‍රධාන සම්පත වන බැවින්", "වැඩිහිටියන් වැදගත් නොවන නිසා", "කර්මාන්තශාලා වැසීමට", "රෝහල් වැඩි කිරීමට", "නිරෝගී හා බුද්ධිමත් තරුණ ප්‍රජාව රටක ආර්ථික හා සමාජීය සංවර්ධනයේ කොඳු නාරටියයි."),
        q("මානසික සුවතාවය පිළිබඳව පාසල තුළ සිසුන් අතර සුහද පරිසරයක් නිර්මාණය කිරීමෙන් අත්වන ප්‍රතිඵලය කුමක්ද?", "සිසුන් අතර සහයෝගීතාව, අන්‍යෝන්‍ය ගරුත්වය, අධ්‍යාපනික දියුණුව සහ ප්‍රීතිමත් පාසල් ජීවිතයක් ඇතිවීම", "හිරිහැර වැඩිවීම", "විභාග ප්‍රතිඵල පහත වැටීම", "ගුරුවරුන් සමග ගැටුම් ඇතිවීම", "ආරක්ෂිත හා සතුටුදායක පාසල් පරිසරයක් සිසුන්ගේ උපරිම කුසලතා එළිදැක්වීමට මග පාදයි."),
        q("යම් පුද්ගලයෙකු මත්ද්‍රව්‍ය අලෙවි කරන පුද්ගලයෙකු පිළිබඳව තොරතුරු දන්නේ නම් කළ යුතු යහපත් පුරවැසි යුතුකම කුමක්ද?", "ආරක්ෂිතව 119 හෝ අදාළ පොලිස් හා මත්ද්‍රව්‍ය නාශක අංශ රහසිගතව දැනුවත් කිරීම", "ඔහුගෙන් මත්ද්‍රව්‍ය මිලදී ගැනීම", "ඔහු සමග මිතුරු වීම", "කිසිවක් නොදැක්කා සේ සිටීම", "මත්ද්‍රව්‍ය ජාවාරම් මැඩලීම සඳහා නීතිමය ආයතනවලට සහය වීම සමාජ වගකීමකි."),
        q("දෛනික ජීවිතයේදී මානසික ආතතිය අඩු කර ගැනීමට ආහාර රටාව බලපාන්නේ කෙසේද?", "පෝෂ්‍යදායී සමබල ආහාර හා ප්‍රමාණවත් ජලය ලබාගැනීමෙන් මොළයේ රසායනික සමතුලිතතාව රැකෙන බැවින්", "කෘත්‍රිම පැණි බීම පමණක් බීමෙන්", "ආහාර වේල් මගහැරීමෙන්", "තෙල් අධික ක්ෂණික ආහාර ගැනීමෙන්", "විටමින් B, ඔමේගා-3 සහ පෝෂ්‍ය පදාර්ථ මොළයේ යහපත් ස්නායු සම්ප්‍රේෂක නිපදවීමට අත්‍යවශ්‍ය වේ."),
        q("පුද්ගලයෙකුගේ ජීවන නිපුණතා ප්‍රගුණ කිරීමේ අවසාන සහ උත්තරීතර ප්‍රතිඵලය කුමක්ද?", "වෙනස් වන ලෝකයේ අභියෝගවලට ධනාත්මකව හා සාර්ථකව මුහුණ දෙමින් සතුටින් හා වගකීමෙන් ජීවත් වීම", "අනුන්ව පාලනය කිරීම", "ධනය රැස් කිරීම පමණක්", "කායික වර්ධනය නතර කිරීම", "ජීවන නිපුණතා යනු සාර්ථක, සදාචාරසම්පන්න හා නිරෝගී පුද්ගලයෙකු බිහි කරන ප්‍රායෝගික අත්පොතයි."),
        q("ගම්, පෙට්‍රල්, තිනර් සහ නිය ආලේපන ඉවත් කරන ද්‍රාවණ ආඝ්‍රාණය කිරීමේ අනතුරුදායක මත්ද්‍රව්‍ය අවභාවිතය හඳුන්වන්නේ කෙසේද?", "ආඝ්‍රාණක ද්‍රව්‍ය අවභාවිතය (Inhalants Abuse)", "නිද්‍රාජනක ඖෂධ භාවිතය", "පෝෂණ අතිරේක භාවිතය", "ස්වාභාවික වාෂ්ප ප්‍රතිකාරය", "වාෂ්පශීලී රසායනික ද්‍රව්‍ය ආඝ්‍රාණයෙන් මොළයේ ස්නායු ක්ෂණිකව විනාශ වී හෘද ස්පන්දනය නතර විය හැක."),
        q("පරිසරයට ඉවත දමන දුම්වැටි කොට (Cigarette Butts) ස්වාභාවික පරිසරයට බරපතළ තර්ජනයක් වන්නේ ඇයි?", "ප්ලාස්ටික් සෙලියුලෝස් ඇසිටේට් පෙරහන් දිරාපත් නොවී පසට හා ජලයට විෂ රසායනික හා ක්ෂුද්‍ර ප්ලාස්ටික් මුදාහරින බැවින්", "ඒවා ඉක්මනින් පොහොර බවට පත්වන නිසා", "කුරුල්ලන්ට ආහාර සපයන නිසා", "ජලය පිරිසිදු කරන නිසා", "දුම්වැටි පෙරහන් දිරාපත් වීමට වසර ගණනාවක් ගත වන අතර ජලජ ජීවීන්ට මාරාන්තික වේ."),
        q("දීර්ඝකාලීන අධික රැකියා හෝ අධ්‍යයන පීඩනය නිසා ඇතිවන පූර්ණ කායික, චිත්තවේගීය හා මානසික විඩාපත්භාවය කුමක්ද?", "දාහ තත්ත්වය හෙවත් බර්න්අවුට් (Burnout)", "යුස්ට්‍රස්", "ස්වයං සංකල්පය", "ප්‍රමුඛතාකරණය", "විවේකයකින් තොරව අඛණ්ඩව අධික පීඩනයක සිටීමෙන් කාර්යක්ෂමතාව සම්පූර්ණයෙන් බිඳ වැටීම Burnout නම් වේ."),
        q("යොවුන් වියේදී මත්පැන් පානය කිරීම මොළයේ පූර්ව ලලාට බාහිකයට (Prefrontal Cortex) හානි කරන්නේ කෙසේද?", "තීරණ ගැනීම, ආවේග පාලනය කිරීම සහ දිගුකාලීන මතක ශක්තිය වර්ධනය වීම බරපතළ ලෙස අඩපණ කිරීමෙන්", "බුද්ධි මට්ටම ක්ෂණිකව ඉහළ දැමීමෙන්", "ඇස් පෙනීම තියුණු කිරීමෙන්", "ශරීර උෂ්ණත්වය ස්ථාවර කිරීමෙන්", "වයස අවුරුදු 25 පමණ වන තෙක් වර්ධනය වන මොළයේ විචාර බුද්ධි කොටසට මධ්‍යසාර ස්ථිර හානි සිදුකරයි."),
        q("ශරීරයේ බර වැඩිවේ යැයි අධික බියක් ඇතිකරගෙන ආහාර ගැනීම අසාමාන්‍ය ලෙස ප්‍රතික්ෂේප කරන මානසික ආහාර ආබාධය කුමක්ද?", "ඇනොරෙක්සියා නර්වෝසා (Anorexia Nervosa)", "ඩවුන් සින්ඩ්‍රෝමය", "සිරෝසිස්", "ඇදුම", "විකෘති ශරීර ප්‍රතිරූපයක් නිසා දැඩි කෙට්ටු බවක් තිබියදීත් තමා මහත යැයි සිතමින් නිරාහාරව සිටීම මෙහි ලක්ෂණයකි."),
        q("එක්වරම අධික ලෙස ආහාර ගෙන පසුව බලෙන් වමනය කිරීමෙන් හෝ විරේක බෙහෙත් ගැනීමෙන් එය පිටකරන මානසික ආබාධය කුමක්ද?", "බුලීමියා නර්වෝසා (Bulimia Nervosa)", "එම්ෆයිසීමා", "තැලසීමියාව", "කාංසා ප්‍රහාරය", "නිතර වමනය කිරීම නිසා ආමාශයික අම්ලය මගින් දත් දිරාපත් වීම හා අන්නස්‍රෝතයට හානි වීම මෙහිදී සිදුවේ."),
        q("දුම්පානය අත්හැරීමට උත්සාහ කරන පුද්ගලයෙකුගේ ඉවත් වීමේ රෝග ලක්ෂණ අවම කිරීමට වෛද්‍යවරුන් නිර්දේශ කරන ප්‍රතිකාර ක්‍රමය කුමක්ද?", "නිකොටින් ප්‍රතිස්ථාපන ප්‍රතිකාරය (Nicotine Replacement Therapy — NRT පැච් හා චුයින්ගම්)", "දුම්වැටි ගණන වැඩි කිරීම", "මත්පැන් පානය කිරීම", "වේප් භාවිතයට හුරු වීම", "තාර හා කාබන් මොනොක්සයිඩ් නොමැතිව පාලිත නිකොටින් මාත්‍රාවක් ක්‍රමයෙන් අඩු කරමින් ලබාදීම මෙහිදී සිදුකෙරේ."),
        q("රජයක් විසින් දුම්වැටි සහ මත්පැන් මත ඉහළ නිෂ්පාදන බදු (Sin Taxes) පැනවීමේ ප්‍රධාන සෞඛ්‍යමය අරමුණ කුමක්ද?", "මිල ඉහළ යාම තුළින් විශේෂයෙන් තරුණ හා අඩු ආදායම්ලාභී පිරිස් ඒවා මිලදී ගැනීම අධෛර්යමත් කිරීම", "මත්පැන් පරිභෝජනය වැඩි කිරීම", "වෙළඳසැල් ප්‍රමාණය වැඩි කිරීම", "වෙළඳ ප්‍රචාරණය දිරිමත් කිරීම", "මිල 10%කින් ඉහළ නැංවූ විට තරුණයන් අතර දුම්කොළ භාවිතය සැලකිය යුතු ප්‍රතිශතයකින් පහත වැටෙන බව WHO පෙන්වා දෙයි."),
        q("ශ්‍රී ලංකාවේ අමද්‍යප ව්‍යාපාරය (Temperance Movement) සමාජ සෞඛ්‍යයට කළ ප්‍රධාන දායකත්වය කුමක්ද?", "මත්පැන් උවදුරට එරෙහිව ජනතාව දැනුවත් කර සදාචාරසම්පන්න හා නිරෝගී සමාජයක් ගොඩනැගීමට මුල් වීම", "මත්පැන් හල් විවෘත කිරීම", "දුම්කොළ වගාව ව්‍යාප්ත කිරීම", "විනෝද ක්‍රීඩා තහනම් කිරීම", "අනගාරික ධර්මපාලතුමා ඇතුළු ජාතික නායකයන් ශ්‍රී ලංකාවේ මත්පැන් විරෝධී සමාජ ප්‍රබෝධයක් ඇති කළහ."),
        q("පන්ති කාමරය තුළ විශේෂ අවශ්‍යතා ඇති හෝ ආර්ථික දුෂ්කරතා ඇති මිතුරෙකුට සමච්චල් නොකර උදව් කිරීමෙන් පිළිබිඹු වන ජීවන නිපුණතාව කුමක්ද?", "සහකම්පනය හා සමාජ වගකීම (Empathy & Social Responsibility)", "ආක්‍රමණශීලීත්වය", "යටහත් පහත් බව", "ස්වයං රැවටීම", "අන් අයගේ දුෂ්කරතා හඳුනාගෙන කරුණාවෙන් හා ගෞරවයෙන් සහය දැක්වීම යහපත් පුරවැසි ලක්ෂණයකි."),
        q("සන්නිවේදනයේදී කථා කරන පුද්ගලයා දෙස සෘජුව හා ප්‍රසන්නව ඇස් සම්බන්ධතාව (Eye Contact) පවත්වා ගැනීමෙන් ප්‍රකාශ වන්නේ කුමක්ද?", "අවධානය, ගෞරවය, අවංකභාවය සහ ආත්ම විශ්වාසය", "කෝපය සහ වෛරය", "බිය සහ පසුබැසීම", "අසත්‍ය පැවසීම", "සුදුසු අයුරින් ඇස් සම්බන්ධතාව පවත්වා ගැනීම ඵලදායී සන්නිවේදනයේ විශ්වාසනීයත්වය තහවුරු කරයි."),
        q("පුද්ගලයෙකු තම අනාගත ඉලක්ක සකස් කිරීමේදී අනුගමනය කරන SMART ආකෘතියේ 'S' සහ 'M' අකුරුවලින් අදහස් කරන්නේ කුමක්ද?", "නිශ්චිත බව (Specific) සහ මැනිය හැකි බව (Measurable)", "සරල බව සහ මිල අධික බව", "සමාජයීය බව සහ මානසික බව", "රහසිගත බව සහ මන්දගාමී බව", "ඉලක්ක නිශ්චිත, මැනිය හැකි, ළඟා විය හැකි, යථාර්ථවාදී හා කාලරාමු සහිත (Time-bound) විය යුතුය."),
        q("දීර්ඝකාලීන අධික මත්පැන් පානය සහ විටමින් B1 (තයමින්) ඌනතාව නිසා ඇතිවන දරුණු මොළයේ හා මතකයේ ආබාධය කුමක්ද?", "වර්නිකේ-කොර්සකොෆ් සින්ඩ්‍රෝමය (Wernicke-Korsakoff Syndrome)", "ඇදුම රෝගය", "පෝලියෝ රෝගය", "ගලගණ්ඩය", "මධ්‍යසාර මගින් විටමින් B1 අවශෝෂණය අඩාල වීමෙන් ස්නායු හානි හා දැඩි අමතක වීමේ තත්ත්වය ඇතිවේ."),
        q("නාගරික පරිසරයේ පවතින අධික ශබ්ද දූෂණය (Noise Pollution) මිනිසාගේ මානසික සෞඛ්‍යයට බලපාන්නේ කෙසේද?", "මානසික ආතතිය, කෝපය, නින්දට බාධා වීම සහ අධ්‍යාපනික ඒකාග්‍රතාව බිඳ වැටීම", "ශ්‍රවණ හැකියාව තියුණු වීම", "මතක ශක්තිය වැඩිවීම", "හෘද ස්පන්දනය සැහැල්ලු වීම", "ඩෙසිබල් 85ට වැඩි අඛණ්ඩ ශබ්ද ස්නායු පද්ධතියට වෙහෙස ගෙන දී ආතති හෝමෝන ඉහළ නංවයි."),
        q("පවුලේ සියලු සාමාජිකයන් දිනපතා එක්ව රාත්‍රී ආහාරය ගනිමින් සුහදව කතාබහ කිරීමෙන් දරුවන්ට ලැබෙන මානසික ප්‍රතිලාභය කුමක්ද?", "පවුලේ බැඳීම ශක්තිමත් වී දරුවන්ගේ මානසික ආරක්ෂාව වැඩිවීම හා අවදානම් හැසිරීම් අඩුවීම", "ආහාර ජීර්ණය අඩාල වීම", "විනෝදය නැති වීම", "අධ්‍යාපනයට බාධා වීම", "පවුලේ සුහද සංවාද තුළින් දරුවන්ගේ ගැටලු කල්තියා හඳුනාගෙන මගපෙන්වීමට අවස්ථාව ලැබේ."),
        q("වැරදි පෙළඹවීමක් හමුවේ මිතුරන්ගේ විහිළු තහළුවලට බිය නොවී හරි දේ වෙනුවෙන් පෙනී සිටීමේ ගුණාංගය කුමක්ද?", "සදාචාරාත්මක ධෛර්යය (Moral Courage)", "ආත්මාර්ථකාමිත්වය", "පක්ෂග්‍රාහී බව", "අවිනිශ්චිතතාව", "සම වයස් පීඩනයට (Peer Pressure) යටත් නොවී තම ප්‍රතිපත්ති රැකගැනීම සැබෑ චරිත ශක්තියයි."),
        q("දුම්කොළ භාවිතය නිසා පවුල් ඒකකයට මෙන්ම ජාතික ආර්ථිකයටද එල්ල වන ප්‍රධාන ආර්ථික බර කුමක්ද?", "දුම්පානය නිසා වැළඳෙන පිළිකා හා හෘද රෝග සඳහා රජයේ සෞඛ්‍ය සේවයට අතිවිශාල මුදලක් වැය වීම", "වගා ඉඩම් වැඩිවීම", "වැඩ කරන පැය ගණන වැඩිවීම", "විදේශ විනිමය ඉතිරි වීම", "දුම්කොළ බදු ආදායමට වඩා කිහිප ගුණයක මුදලක් එම රෝගීන්ගේ ප්‍රතිකාර හා ශ්‍රම හානිය වෙනුවෙන් වැය වේ."),
        q("නොදන්නා පුද්ගලයෙකු ලබාදෙන පැණි රස කෑමක්, ටොෆි හෝ බීමක් ප්‍රතික්ෂේප කළ යුත්තේ මන්ද?", "ඒවා තුළ මත්ද්‍රව්‍ය හෝ නිද්‍රාකාරක රසායනික සඟවා තිබිය හැකි බැවින් (Spiked Substances)", "සීනි අඩු බැවින්", "මිල අධික බැවින්", "ප්‍රමාණය කුඩා බැවින්", "පාසල් අසල දරුවන් රවටා ඇබ්බැහි කරවීමට මත්ද්‍රව්‍ය මිශ්‍ර කළ රසකැවිලි යොදාගන්නා අවස්ථා වාර්තා වේ."),
        q("තමාගේ සිතට දැනෙන දැඩි දුක හෝ කෝපය දිනපොතක සටහන් කිරීමෙන් (Journaling) මනසට සිදුවන යහපත කුමක්ද?", "හිතේ සිරවී ඇති පීඩාකාරී හැඟීම් පිටතට මුදාහැරී (Catharsis) මනසට පැහැදිලි බවක් හා සැහැල්ලුවක් දැනීම", "කෝපය තවත් වැඩිවීම", "කාලය නාස්ති වීම", "මතකය නැති වීම", "හැඟීම් වචනවලට පෙරළීමෙන් ගැටලුව දෙස මධ්‍යස්ථව බලා විසඳුම් සිතීමට පහසු වේ."),
        q("සම වයසේ පුහුණු සිසුන් මගින් අනෙකුත් සිසුන්ට මත්ද්‍රව්‍ය හා මානසික සෞඛ්‍යය පිළිබඳ දැනුම ලබාදීමේ වැඩසටහන් ක්‍රමය කුමක්ද?", "සම වයස් අධ්‍යාපනය (Peer Education)", "දැඩි විනය පරීක්ෂණය", "ඒකපාර්ශ්වික දේශනය", "හුදකලා අධ්‍යයනය", "තරුණ දරුවන් වැඩිහිටියන්ගේ අවවාදවලට වඩා තම සම වයස් මිතුරන්ගේ නිවැරදි මගපෙන්වීමට සංවේදී වේ."),
        q("මොළයේ සතුට, අභිප්‍රේරණය සහ චිත්තවේගීය සමතුලිතතාව පාලනය කරන ප්‍රධාන ස්නායු සම්ප්‍රේෂක (Neurotransmitters) දෙක කුමක්ද?", "ඩෝපමයින් (Dopamine) සහ සෙරොටොනින් (Serotonin)", "ඉන්සියුලින් සහ තයිරොක්සින්", "පෙප්සින් සහ ඇමයිලේස්", "හිමොග්ලොබින් සහ ෆයිබ්‍රිනෝජන්", "නිරෝගී නින්ද, ව්‍යායාම හා සමබල ආහාර මගින් මෙම රසායන ස්වාභාවිකව සමතුලිත කෙරේ."),
        q("පාඩම් කිරීමට නිදි මැරීම සඳහා අධික කැෆේන් හා සීනි අඩංගු ශක්තිජනක පාන (Energy Drinks) නිතර පානය කිරීමේ අහිතකර ප්‍රතිඵලය කුමක්ද?", "හෘද ස්පන්දන අක්‍රමිකතා, කාංසාව, නින්ද බිඳ වැටීම සහ රුධිර පීඩනය ඉහළ යාම", "මතක ශක්තිය ස්ථිරව වැඩිවීම", "මාංශ පේශි ශක්තිමත් වීම", "සිරුර සිසිල් වීම", "කෘත්‍රිම උත්තේජක පාන මගින් තාවකාලික අවදි බවක් ලැබුණද ස්නායු හා හෘද පද්ධතියට දැඩි වෙහෙසක් ගෙනදේ."),
        q("තරගයකට පෙර ක්‍රීඩකයෙකු තමා සාර්ථකව ක්‍රීඩා කරන ආකාරය මනසින් දැකීම (Mental Imagery / Visualization) මගින් ලැබෙන වාසිය කුමක්ද?", "ආත්ම විශ්වාසය ඉහළ ගොස් තරග කාංසාව අඩු වී ක්‍රීඩා කාර්ය සාධනය වැඩිදියුණු වීම", "ශාරීරික වෙහෙස වැඩිවීම", "නීති රීති අමතක වීම", "මාංශ පේශි දුර්වල වීම", "ක්‍රීඩා මනෝවිද්‍යාවේදී මානසික පෙරහුරුව ස්නායු-පේශි සම්බන්ධීකරණය පවා උත්තේජනය කරයි."),
        q("කණ්ඩායම් ක්‍රීඩාවල නිරත වීමෙන් දරුවෙකු තුළ වර්ධනය වන ප්‍රධාන සමාජ ජීවන නිපුණතා මොනවාද?", "සහයෝගීතාව, නායකත්වය, නීති ගරුකිරීම සහ ජය පරාජය සමසේ දරාගැනීම", "තනිවම බලය පැතිරවීම", "අන් අයට ඊර්ෂ්‍යා කිරීම", "පරාජයේදී කලහකාරී වීම", "ක්‍රීඩා පිටිය යනු ජීවන නිපුණතා ප්‍රායෝගිකව පුහුණු වන හොඳම විද්‍යාගාරයයි."),
        q("යමෙකු තමාගේ අඩුපාඩුවක් පෙන්වා දුන් විට කෝප නොවී එය තමාගේ දියුණුවට යොදාගැනීමේ ගුණාංගය කුමක්ද?", "ධනාත්මක විවේචන පිළිගැනීමේ හැකියාව (Accepting Constructive Criticism)", "ආක්‍රමණශීලී ප්‍රතිචාරය", "පළිගැනීමේ චේතනාව", "ස්වයං දෝෂාරෝපණය", "වැරදි හඳුනාගෙන නිවැරදි කරගැනීමට කැමති වීම පෞරුෂ සංවර්ධනයේ ඉහළ ලක්ෂණයකි."),
        q("'දුම්වැටියක් ඉරීමෙන් මානසික ආතතිය සම්පූර්ණයෙන්ම නැති වේ' යන මිථ්‍යා මතය පිළිබඳ විද්‍යාත්මක සත්‍යය කුමක්ද?", "එය නිකොටින් ඉවත් වීමේ වේදනාව තාවකාලිකව යටපත් කිරීමක් පමණක් වන අතර දිගුකාලීනව කාංසාව තවත් වැඩි කරයි", "එය 100%ක්ම සත්‍ය ප්‍රතිකාරයකි", "නිකොටින් ස්නායු සුවපත් කරයි", "දුම්පානය මොළයට ඔක්සිජන් සපයයි", "නිකොටින් මට්ටම බැස යන විට ඇතිවන නොසන්සුන් බව තවත් දුම්වැටියකින් සමනය වීම ආතතිය නැති වීමක් ලෙස වරදවා වටහා ගැනේ."),
        q("නිවසේ පියා හෝ සාමාජිකයෙකු මත්පැන්වලට ඇබ්බැහි වීම නිසා පීඩා විඳින පවුලේ අයට ගත යුතු නිවැරදි පියවර කුමක්ද?", "වෛද්‍යවරයෙකු හෝ පවුල් උපදේශන සේවා සහය පතමින් ආරක්ෂිතව පුනරුත්ථාපනය සඳහා ඔහුව යොමු කිරීම", "සැමදා නිහඬව ගෘහස්ථ හිංසනය ඉවසීම", "දරුවන්ද එයට හුරු වීම", "අධික කෝපයෙන් පහර දීම", "මත්පැන් ඇබ්බැහිය පවුලේ සියල්ලන්ට බලපාන බැවින් වෘත්තීය උපදේශන සහය ලබාගැනීම අත්‍යවශ්‍ය වේ."),
        q("මානසික ආතතියට පත් වූ පුද්ගලයෙකු තුළ දක්නට ලැබෙන 'චර්යාත්මක රෝග ලක්ෂණයක්' (Behavioral Sign) වන්නේ කුමක්ද?", "නියපොතු සැපීම, දත් මිටි කෑම, හදිසි කෝපය පිටකිරීම සහ සමාජයෙන් ඈත් වීම", "රුධිරයේ සීනි මට්ටම පරීක්ෂා කිරීම", "නිතිපතා ව්‍යායාම කිරීම", "පිරිසිදුව ඇඳුම් ඇඳීම", "වෙනදා කළ ප්‍රියතම කටයුතු අතහැරීම හා අසාමාන්‍ය නොසන්සුන් චර්යා ආතතියේ සලකුණු වේ."),
        q("මානසික ආතතිය නිසා ඇතිවන 'ඥානාත්මක රෝග ලක්ෂණයක්' (Cognitive Sign) ලෙස හඳුනාගත හැක්කේ කුමක්ද?", "අමතක වීම, අවධානය රඳවා ගැනීමට නොහැකි වීම සහ නිවැරදි තීරණ ගැනීමේ අපහසුතාව", "උදර වේදනාව පමණි", "සමේ කැසීම", "හන්දිපත් ඉදිමීම", "අධික කෝටිසෝල් මට්ටම මොළයේ හිපොකැම්පස් කොටසට බලපෑම් කර මතකය හා අවධානය දුර්වල කරයි."),
        q("මානසික ආතතියේදී පෙන්නුම් කරන 'චිත්තවේගීය ලක්ෂණයක්' (Emotional Sign) වන්නේ පහත සඳහන් කුමක්ද?", "නිතර කලබලය, බලාපොරොත්තු සුන් වූ බවක් දැනීම, අසරණභාවය සහ නුරුස්නා බව", "රුධිරයේ රතු සෛල වැඩිවීම", "උස වැඩිවීම", "මාංශ පේශි වර්ධනය", "ආතතිය කළමනාකරණය නොකළ විට චිත්තවේගීය සමතුලිතතාව බිඳ වැටී නිතර හැඬීමට හෝ කේන්ති යෑමට ඉඩ තිබේ."),
        q("ගැටලුවක් විසඳීම සඳහා කණ්ඩායමක් එක්ව කිසිදු අදහසක් විවේචනය නොකර හැකිතාක් නව අදහස් ඉදිරිපත් කිරීමේ නිර්මාණශීලී ක්‍රමය කුමක්ද?", "මොළය කැළඹීමේ ක්‍රමය හෙවත් බ්‍රේන්ස්ටෝමින් (Brainstorming)", "ඒකාධිපති තීරණය", "අනුකරණය කිරීම", "දෝෂාරෝපණය කිරීම", "Brainstorming තුළින් බහුවිධ නිර්මාණශීලී විසඳුම් අතරින් හොඳම විසඳුම තෝරාගත හැක."),
        q("පුද්ගලයෙකු තම හැඟීම් පාලනය කරගැනීමට පමණක් නොව අන් අයගේ හැඟීම් හඳුනාගෙන සබඳතා පවත්වා ගැනීමට ඇති බුද්ධිය කුමක්ද?", "චිත්තවේග බුද්ධිය (Emotional Intelligence — EQ)", "ගණිතමය බුද්ධිය", "අවකාශමය බුද්ධිය", "ශාරීරික ශක්තිය", "ජීවිතයේ සාර්ථකත්වය සඳහා බුද්ධි ඵලයට (IQ) සමානව හෝ ඊටත් වඩා චිත්තවේග බුද්ධිය (EQ) වැදගත් වේ."),
        q("අන් අයට හිරිහැර නොකරන නමුත් කේලාම් කීම, මුහුණ ඇඹුල් කිරීම හෝ වැඩ කඩාකප්පල් කිරීම මගින් වක්‍රව කෝපය පිටකිරීමේ හැසිරීම කුමක්ද?", "අක්‍රීය-ආක්‍රමණශීලී හැසිරීම (Passive-Aggressive Behavior)", "තහවුරුශීලී හැසිරීම", "සහකම්පනීය හැසිරීම", "වෘත්තීය හැසිරීම", "අසතුට සෘජුව හා සුහදව ප්‍රකාශ කිරීම වෙනුවට වක්‍ර ක්‍රමවලින් හානි කිරීම සබඳතා විනාශ කරයි."),
        q("රාත්‍රී නින්දට පෙර පැයක පමණ කාලයක් ජංගම දුරකථන හා රූපවාහිනී තිරවලින් ඈත්ව සිටීම නිර්දේශ කරන්නේ ඇයි?", "තිරවලින් නිකුත් වන නිල් ආලෝකය (Blue Light) නිසා නින්දට අවශ්‍ය මෙලටොනින් හෝමෝනය නිපදවීම අඩාල වන බැවින්", "දුරකථනයේ බැටරිය ඉතිරි කිරීමට පමණි", "ඇස්වල වර්ණය වෙනස් වන නිසා", "කුසගින්න ඇතිවන නිසා", "යහපත් නින්ද ස්වස්ථතාව (Sleep Hygiene) මානසික සුවතාවය හා මතක ශක්තිය රැකගැනීමට අත්‍යවශ්‍ය වේ."),
        q("බහුසංස්කෘතික සමාජයක විවිධ ආගම්, ජාතීන් හා අදහස් දරන පුද්ගලයන්ට ගරු කරමින් සමගියෙන් ජීවත් වීමෙන් මනසට ලැබෙන ප්‍රතිඵලය කුමක්ද?", "සමාජ සාමය, අන්‍යෝන්‍ය විශ්වාසය සහ ආතතියෙන් තොර සහජීවනය ඇතිවීම", "වෛරය වර්ධනය වීම", "ගැටුම් උත්සන්න වීම", "හුදකලා බව වැඩිවීම", "විවිධත්වය අගය කිරීම මානසික පීඩනය අවම කර සමාජ සෞඛ්‍යය ශක්තිමත් කරයි."),
        q("පාසලේ හෝ ගමේ ප්‍රජා සේවා කටයුතුවලට (ශ්‍රමදාන, රුක් රෝපණ, වැඩිහිටි උපකාර) ස්වේච්ඡාවෙන් දායක වීමෙන් ලැබෙන මානසික වාසිය කුමක්ද?", "සමාජ අර්ථවත්භාවය, ආත්ම තෘප්තිය සහ මානසික අවපීඩනයෙන් ආරක්ෂා වීම", "කාලය අපතේ යාම", "මානසික ආතතිය වැඩිවීම", "පාඩම් අමතක වීම", "අනුන්ට උපකාර කිරීමේදී මොළයේ සතුට දනවන රසායන ස්‍රාවය වී ජීවිතයට අර්ථයක් ලැබේ."),
        q("දීර්ඝකාලීන අසහනය හා කෝටිසෝල් අධික වීම නිසා පුද්ගලයාගේ ශාරීරික ප්‍රතිශක්තිකරණ පද්ධතියට සිදුවන බලපෑම කුමක්ද?", "සුදු රුධිරාණු ක්‍රියාකාරිත්වය දුර්වල වී බෝවන රෝග හා තුවාල සුව වීම ප්‍රමාද වීම", "ප්‍රතිශක්තිය දෙගුණ වීම", "රතු රුධිරාණු වැඩිවීම", "අස්ථි ඝනත්වය වැඩිවීම", "මනස සහ ශරීරය එකිනෙකට බැඳී ඇති බැවින් මානසික පීඩනය කායික රෝග වේගවත් කරයි."),
        q("දුම්වැටිවල අඩංගු විෂ රසායනික ද්‍රව්‍ය සමේ රුධිර සංසරණය අඩු කර කොලජන් විනාශ කිරීම නිසා ඇතිවන බාහිර ලක්ෂණය කුමක්ද?", "සම අකලට රැළි වැටීම හා වයස්ගත පෙනුමක් ඇතිවීම (Premature Aging)", "සම දීප්තිමත් වීම", "හිසකෙස් ඝන වීම", "නියපොතු ශක්තිමත් වීම", "දුම්පානය මගින් සමේ සෛලවලට ඔක්සිජන් සැපයුම අඩාල වී අකලට වියපත් වීම සිදුවේ."),
        q("මත්ද්‍රව්‍ය භාවිතයට යොමු වීම සඳහා පළමු පියවර ලෙස ක්‍රියා කරන බැවින් 'දොරටු මත්ද්‍රව්‍ය' (Gateway Drugs) ලෙස හඳුන්වන්නේ මොනවාද?", "දුම්වැටි, බුලත්විට-දුම්කොළ සහ මධ්‍යසාර වැනි මුලින් අත්හදා බලන ද්‍රව්‍ය", "වෛද්‍යවරුන් දෙන ප්‍රතිජීවක", "විටමින් පෙති", "පිරිසිදු පානීය ජලය", "බොහෝ විට හෙරොයින් හෝ අයිස් වැනි දරුණු මත්ද්‍රව්‍යවලට ඇබ්බැහි වීම ආරම්භ වන්නේ දුම්වැටි හා මත්පැන් හරහාය."),
        q("වැරදීමකින් හෝ පරාජයකින් පසු 'මට කිසිවක් බැහැ' යැයි සිතා පසුබසිනවා වෙනුවට එම වැරැද්දෙන් පාඩමක් ඉගෙන ගැනීමේ චින්තනය කුමක්ද?", "වර්ධන මානසිකත්වය (Growth Mindset)", "ස්ථාවර හා පසුගාමී මානසිකත්වය", "ආත්මානුකම්පාව", "උදාසීනත්වය", "වෑයම සහ පුහුණුව තුළින් ඕනෑම හැකියාවක් දියුණු කළ හැකි බව විශ්වාස කිරීම Growth Mindset වේ."),
        q("අධික මත්පැන් පානය නිසා අක්මා සෛල තුළ අසාමාන්‍ය ලෙස මේදය තැන්පත් වීමේ මුල් අවස්ථාව හඳුන්වන්නේ කෙසේද?", "මේදමය අක්මාව (Alcoholic Fatty Liver)", "අක්මා පිළිකාව පමණි", "වකුගඩු ගල්", "හෘදයාබාධය", "මත්පැන් නතර කළහොත් Fatty Liver තත්ත්වය සුව කළ හැකි නමුත් දිගටම පානය කළහොත් එය සිරෝසිස් බවට පත්වේ."),
        q("ප්‍රමාණවත් ඉතුරුම් නොමැතිව හදිසි ආවේගයට අනවශ්‍ය භාණ්ඩ මිලදී ගැනීමෙන් මනසට ඇතිවන අහිතකර බලපෑම කුමක්ද?", "ණය බර හා මූල්‍යමය මානසික ආතතිය ඇතිවීම", "ආත්ම විශ්වාසය වැඩිවීම", "පවුලේ සතුට වැඩිවීම", "නින්ද සුවදායී වීම", "වගකිවයුතු මූල්‍ය කළමනාකරණය (Financial Literacy) වැඩිහිටි ජීවිතයේ මානසික සුවතාව රැකගැනීමට අවශ්‍ය ජීවන නිපුණතාවකි."),
        q("දෛනිකව තමාට ලැබුණු යහපත් දේ පිළිබඳව කෘතඥතාව දැක්වීමේ පුරුද්ද (Gratitude Practice) මානසික සෞඛ්‍යයට උපකාරී වන්නේ කෙසේද?", "මනසේ ධනාත්මක බව වැඩි කර කාංසාව හා ඊර්ෂ්‍යාව අවම කර ගැනීමට", "ආත්මාර්ථකාමිත්වය වැඩි කිරීමට", "අලස බව ඇති කිරීමට", "අන් අයව පහත් කිරීමට", "තමා සතු දේ අගය කිරීම තෘප්තිමත් හා සාමකාමී මනසක් ගොඩනගන සරල විද්‍යාත්මක ක්‍රමයකි."),
        q("වර්තමාන මොහොතේ තමා අත්විඳින දේ කෙරෙහි කිසිදු විනිශ්චයකින් තොරව පූර්ණ අවධානය යොමු කිරීමේ මානසික පුහුණුව කුමක්ද?", "සිහිනුවණ හෙවත් සතිපට්ඨාන අවධානය (Mindfulness)", "අතීතය ගැන පසුතැවීම", "අනාගත බිය", "වික්ෂිප්ත බව", "Mindfulness පුහුණුව මගින් අනවශ්‍ය සිතුවිලි කැළඹීම් සමනය වී සාමකාමී ඒකාග්‍රතාවක් ඇතිවේ."),
        q("දුම්පානය හෝ මත්ද්‍රව්‍ය අත්හැරීමට උත්සාහ කරන තරුණයෙකුට අධි අවදානම් අවස්ථා (High-risk Situations) මගහැරීම වැදගත් වන්නේ ඇයි?", "පැරණි පුරුදු උත්තේජනය වී නැවත ඇබ්බැහි වීමේ (Relapse) අවදානම වළක්වා ගැනීමට", "මිතුරන් නොමැතිවීමට", "ශරීර බර අඩු කිරීමට", "නින්ද අඩු කිරීමට", "මත්ද්‍රව්‍ය භාවිත කරන ස්ථාන හා පුද්ගලයන්ගෙන් ඉවත් වී නව සෞඛ්‍ය සම්පන්න විනෝදාංශවල යෙදීම සුවය ස්ථිර කරයි.")
    )
}
